package com.nexora.shared.i18n;

import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.Instant;
import java.util.Locale;
import java.util.Map;

/**
 * Kazakh labels for values that appear inside user-facing messages generated by the backend
 * (state names in errors, notification texts, dates). Internal codes and enum names stay unchanged;
 * only their human-readable form is localized here.
 */
public final class Kk {

    public static final Locale LOCALE = Locale.forLanguageTag("kk-KZ");

    private static final DateTimeFormatter DATE_TIME = DateTimeFormatter.ofPattern("d MMMM, HH:mm", LOCALE);

    private static final Map<String, String> STATUS = Map.ofEntries(
            // flight bookings
            Map.entry("PENDING", "Күтуде"), Map.entry("CONFIRMED", "Расталған"), Map.entry("CANCELLED", "Болдырылмаған"),
            Map.entry("EXPIRED", "Мерзімі өткен"),
            // documents
            Map.entry("DRAFT", "Қаралама"), Map.entry("PENDING_APPROVAL", "Бекітуді күтуде"), Map.entry("IN_REVIEW", "Қаралуда"),
            Map.entry("APPROVED", "Бекітілген"), Map.entry("REJECTED", "Қабылданбаған"),
            // appointments
            Map.entry("SCHEDULED", "Жоспарланған"), Map.entry("COMPLETED", "Аяқталған"), Map.entry("NO_SHOW", "Келмеді"));

    private static final Map<String, String> OPERATION = Map.ofEntries(
            Map.entry("confirm", "растау"), Map.entry("cancel", "болдырмау"), Map.entry("expire", "мерзімін аяқтау"),
            Map.entry("edit", "өңдеу"), Map.entry("submit", "бекітуге жіберу"), Map.entry("approve", "бекіту"),
            Map.entry("reject", "қабылдамау"), Map.entry("return", "пысықтауға қайтару"),
            Map.entry("return for revision", "пысықтауға қайтару"), Map.entry("reschedule", "басқа уақытқа ауыстыру"));

    private static final Map<String, String> ENTITY_ACCUSATIVE = Map.of(
            "booking", "брондауды", "document", "құжатты", "appointment", "жазылуды");

    private Kk() {
    }

    public static String status(String code) {
        return STATUS.getOrDefault(code, code);
    }

    private static final Map<String, String> ROLE = Map.of(
            "ADMIN", "Әкімші", "MANAGER", "Менеджер", "DOCTOR", "Дәрігер", "EMPLOYEE", "Қызметкер", "USER", "Пайдаланушы");

    private static final Map<String, String> REPLENISHMENT = Map.of(
            "TOP_UP_TO_TARGET", "ең аз қордың 3 есесіне дейін толықтыру",
            "FIXED_LOT", "50 бірліктік тұрақты партиялар",
            "DEMAND_BASED", "сұранысқа негізделген");

    /** 1500000.00 -> "1 500 000 ₸" (non-breaking spaces). */
    public static String money(java.math.BigDecimal amount) {
        String digits = amount.setScale(0, java.math.RoundingMode.HALF_UP).toPlainString();
        return digits.replaceAll("\\B(?=(\\d{3})+(?!\\d))", "\u00A0") + "\u00A0₸";
    }

    /** Booking actions offered by a State object: confirm -> растау. */
    public static String actions(java.util.Collection<String> actions) {
        return actions.isEmpty() ? "жоқ" : String.join(", ", actions.stream().sorted().map(Kk::operation).toList());
    }

    public static String replenishment(String code) {
        return REPLENISHMENT.getOrDefault(code, code);
    }

    public static String role(String code) {
        return ROLE.getOrDefault(code, code);
    }

    public static String operation(String op) {
        if (op.startsWith("move to ")) {
            return "«" + status(op.substring(8)) + "» күйіне ауыстыру";
        }
        return OPERATION.getOrDefault(op, op);
    }

    public static String entityAccusative(String entity) {
        return ENTITY_ACCUSATIVE.getOrDefault(entity, entity);
    }

    public static String dateTime(Instant instant, ZoneId zone) {
        return instant == null ? "-" : DATE_TIME.format(instant.atZone(zone));
    }
}
